INSERT INTO `wp_wfissues` VALUES (959, 1710025097, 1710025097, 'ignoreC', 'wfPluginVulnerable', 100, 'afe2ee3f1202deb7391d9d2c94b81cc4', 'afe2ee3f1202deb7391d9d2c94b81cc4', 'The Plugin "Advanced Custom Fields PRO" has a security vulnerability.', 'To protect your site from this vulnerability, the safest option is to deactivate and completely remove "Advanced Custom Fields PRO" until a patched version is available. <a href="https://www.wordfence.com/help/?query=scan-result-plugin-vulnerable" target="_blank" rel="noopener noreferrer">Get more information.<span class="screen-reader-text"> (opens in new tab)</span></a>', 'a:24:{s:4:"Name";s:26:"Advanced Custom Fields PRO";s:9:"PluginURI";s:36:"https://www.advancedcustomfields.com";s:7:"Version";s:5:"6.2.0";s:11:"Description";s:69:"Customize WordPress with powerful, professional and intuitive fields.";s:6:"Author";s:9:"WP Engine";s:9:"AuthorURI";s:131:"https://wpengine.com/?utm_source=wordpress.org&utm_medium=referral&utm_campaign=plugin_directory&utm_content=advanced_custom_fields";s:10:"TextDomain";s:3:"acf";s:10:"DomainPath";s:5:"/lang";s:7:"Network";b:0;s:10:"RequiresWP";s:0:"";s:11:"RequiresPHP";s:0:"";s:9:"UpdateURI";s:40:"https://www.advancedcustomfields.com/pro";s:5:"Title";s:26:"Advanced Custom Fields PRO";s:10:"AuthorName";s:9:"WP Engine";s:10:"pluginFile";s:92:"/www/villanova_www/www/villa_load_fast/wp-content/plugins/advanced-custom-fields-pro/acf.php";s:4:"slug";s:26:"advanced-custom-fields-pro";s:10:"vulnerable";b:1;s:17:"vulnerabilityLink";s:108:"https://www.wordfence.com/threat-intel/vulnerabilities/id/e3593dfd-7b2a-4d01-8af0-725b444dc81b?source=plugin";s:9:"cvssScore";s:3:"6.4";s:13:"severityColor";s:7:"#f9a009";s:13:"severityLabel";s:7:"Średni";s:13:"severityClass";s:32:"wf-vulnerability-severity-medium";s:10:"cvssVector";s:44:"CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:C/C:L/I:L/A:N";s:16:"updatedAvailable";b:0;}'),
 (1207, 1713652334, 1713652334, 'new', 'knownfile', 50, 'f19e2322ee4b6e4bb759040d3b01178c', 'a9054b23716615b4420137cd9964738d', 'Zmodyfikowany plik wtyczki: wp-content/plugins/wp-htaccess-editor/wp-htaccess-editor.php', 'This file belongs to plugin "WP Htaccess Editor" version "1.71" and has been modified from the file that is distributed by WordPress.org for this version. Please use the link to see how the file has changed. If you have modified this file yourself, you can safely ignore this warning. If you see a lot of changed files in a plugin that have been made by the author, then try uninstalling and reinstalling the plugin to force an upgrade. Doing this is a workaround for plugin authors who don\'t manage their code correctly. <a href="https://www.wordfence.com/help/?query=scan-result-modified-plugin" target="_blank" rel="noopener noreferrer">Learn More<span class="screen-reader-text"> (otwiera się w nowej karcie)</span></a>', 'a:10:{s:4:"file";s:60:"wp-content/plugins/wp-htaccess-editor/wp-htaccess-editor.php";s:8:"realFile";s:99:"/www/villanova_www/www/villa_load_fast/wp-content/plugins/wp-htaccess-editor/wp-htaccess-editor.php";s:5:"cType";s:6:"plugin";s:7:"canDiff";b:1;s:6:"canFix";b:1;s:9:"canDelete";b:0;s:5:"cName";s:18:"WP Htaccess Editor";s:8:"cVersion";s:4:"1.71";s:4:"cKey";s:41:"wp-htaccess-editor/wp-htaccess-editor.php";s:10:"haveIssues";s:7:"plugins";}'),
 (1208, 1713652694, 1713652694, 'new', 'file', 100, 'e1b812552d5c9f41a77a9c9f4e566ed1', '7be49a86cc64184c02c380757bb484e1', 'Plik wydaje się złośliwy lub niebezpieczny: statystyka/usage_202404.html', 'Wygląda na to, że ten plik został zainstalowany lub zmodyfikowany przez hakera w celu wykonania złośliwej aktywności. Jeśli wiesz o tym pliku, możesz go zignorować, aby wykluczyć go z przyszłych skanowań. Dopasowany tekst w tym pliku to: <strong style="color: #F00;" class="wf-split-word">cat /etc/passwd</strong> <br><br>Typ problemu to: <strong>Backdoor:SH/passwdaccess.60</strong><br>Opis: <strong>Theft of server password information.  Also sometimes seen in a backdoor known as Liz0ziM</strong>', 'a:9:{s:4:"file";s:28:"statystyka/usage_202404.html";s:8:"realFile";s:67:"/www/villanova_www/www/villa_load_fast/statystyka/usage_202404.html";s:4:"shac";s:64:"8EF10E3D9B685B2706D16844A1A3FDFA8AC9AA28BB383C69D5D0580C2ACAFEFB";s:9:"highSense";b:0;s:7:"canDiff";b:0;s:6:"canFix";b:0;s:9:"canDelete";b:1;s:13:"canRegenerate";b:0;s:8:"wpconfig";b:0;}'),
 (1218, 1713868373, 1713868373, 'new', 'wfPluginUpgrade', 50, 'cabcc5e3abe0326f54902f91c48767d8', 'cabcc5e3abe0326f54902f91c48767d8', 'Wtyczka „Site Kit by Google” wymaga uaktualnienia (1.124.0 -> 1.125.0).', 'Musisz zaktualizować "Site Kit by Google" do najnowszej wersji, aby mieć pewność, że masz wszelkie poprawki bezpieczeństwa wydane przez programistę.', 'a:21:{s:4:"Name";s:18:"Site Kit by Google";s:9:"PluginURI";s:30:"https://sitekit.withgoogle.com";s:7:"Version";s:7:"1.124.0";s:11:"Description";s:125:"Site Kit is a one-stop solution for WordPress users to use everything Google has to offer to make them successful on the web.";s:6:"Author";s:6:"Google";s:9:"AuthorURI";s:29:"https://opensource.google.com";s:10:"TextDomain";s:15:"google-site-kit";s:10:"DomainPath";s:0:"";s:7:"Network";b:0;s:10:"RequiresWP";s:3:"5.2";s:11:"RequiresPHP";s:3:"5.6";s:9:"UpdateURI";s:0:"";s:15:"RequiresPlugins";s:0:"";s:5:"Title";s:18:"Site Kit by Google";s:10:"AuthorName";s:6:"Google";s:10:"pluginFile";s:93:"/www/villanova_www/www/villa_load_fast/wp-content/plugins/google-site-kit/google-site-kit.php";s:4:"slug";s:15:"google-site-kit";s:10:"newVersion";s:7:"1.125.0";s:5:"wpURL";s:45:"https://wordpress.org/plugins/google-site-kit";s:15:"updateAvailable";b:1;s:10:"vulnerable";b:0;}'),
 (1219, 1713868373, 1713868373, 'new', 'wfPluginUpgrade', 50, '2ed5a74b94d327776b1b75e354630b4c', '2ed5a74b94d327776b1b75e354630b4c', 'Wtyczka „WPS Hide Login” wymaga uaktualnienia (1.9.13.2 -> 1.9.15.2).', 'Musisz zaktualizować "WPS Hide Login" do najnowszej wersji, aby mieć pewność, że masz wszelkie poprawki bezpieczeństwa wydane przez programistę.', 'a:21:{s:4:"Name";s:14:"WPS Hide Login";s:9:"PluginURI";s:0:"";s:7:"Version";s:8:"1.9.13.2";s:11:"Description";s:132:"Protect your website by changing the login URL and preventing access to wp-login.php page and wp-admin directory while not logged-in";s:6:"Author";s:36:"WPServeur, NicolasKulka, wpformation";s:9:"AuthorURI";s:21:"https://wpserveur.net";s:10:"TextDomain";s:14:"wps-hide-login";s:10:"DomainPath";s:9:"languages";s:7:"Network";b:0;s:10:"RequiresWP";s:3:"4.1";s:11:"RequiresPHP";s:3:"7.0";s:9:"UpdateURI";s:0:"";s:15:"RequiresPlugins";s:0:"";s:5:"Title";s:14:"WPS Hide Login";s:10:"AuthorName";s:36:"WPServeur, NicolasKulka, wpformation";s:10:"pluginFile";s:91:"/www/villanova_www/www/villa_load_fast/wp-content/plugins/wps-hide-login/wps-hide-login.php";s:4:"slug";s:14:"wps-hide-login";s:10:"newVersion";s:8:"1.9.15.2";s:5:"wpURL";s:44:"https://wordpress.org/plugins/wps-hide-login";s:15:"updateAvailable";b:1;s:10:"vulnerable";b:0;}'),
 (1220, 1713868373, 1713868373, 'new', 'wfPluginUpgrade', 50, '12e73fc76ba36887e77145196d58db10', '12e73fc76ba36887e77145196d58db10', 'Wtyczka „Yoast SEO” wymaga uaktualnienia (22.4 -> 22.5).', 'Musisz zaktualizować "Yoast SEO" do najnowszej wersji, aby mieć pewność, że masz wszelkie poprawki bezpieczeństwa wydane przez programistę.', 'a:21:{s:4:"Name";s:9:"Yoast SEO";s:9:"PluginURI";s:18:"https://yoa.st/1uj";s:7:"Version";s:4:"22.4";s:11:"Description";s:117:"The first true all-in-one SEO solution for WordPress, including on-page content analysis, XML sitemaps and much more.";s:6:"Author";s:10:"Team Yoast";s:9:"AuthorURI";s:18:"https://yoa.st/1uk";s:10:"TextDomain";s:13:"wordpress-seo";s:10:"DomainPath";s:11:"/languages/";s:7:"Network";b:0;s:10:"RequiresWP";s:3:"6.3";s:11:"RequiresPHP";s:5:"7.2.5";s:9:"UpdateURI";s:0:"";s:15:"RequiresPlugins";s:0:"";s:5:"Title";s:9:"Yoast SEO";s:10:"AuthorName";s:10:"Team Yoast";s:10:"pluginFile";s:82:"/www/villanova_www/www/villa_load_fast/wp-content/plugins/wordpress-seo/wp-seo.php";s:4:"slug";s:13:"wordpress-seo";s:10:"newVersion";s:4:"22.5";s:5:"wpURL";s:43:"https://wordpress.org/plugins/wordpress-seo";s:15:"updateAvailable";b:1;s:10:"vulnerable";b:0;}'),
 (1221, 1713868373, 1713868373, 'new', 'wfThemeUpgrade', 50, 'ed0ea811232d120f777322f3f5b85d2c', 'ed0ea811232d120f777322f3f5b85d2c', 'Motyw „Twenty Twenty-Four” wymaga uaktualnienia (1.0 -> 1.1).', 'Musisz zaktualizować "Twenty Twenty-Four" do najnowszej wersji, aby mieć pewność, że masz wszelkie poprawki bezpieczeństwa wydane przez programistę.', 'a:7:{s:10:"newVersion";s:3:"1.1";s:7:"package";s:62:"https://downloads.wordpress.org/theme/twentytwentyfour.1.1.zip";s:3:"URL";s:46:"https://wordpress.org/themes/twentytwentyfour/";s:4:"Name";s:18:"Twenty Twenty-Four";s:4:"name";s:18:"Twenty Twenty-Four";s:7:"version";s:3:"1.0";s:10:"vulnerable";b:0;}');
